import {equipmentDisplayQuality} from './equipment-display.js';
import {equipmentIcon} from './equipment-art.js';
import {SLOTNAME,RARITY} from './engine.js';
import {icon} from './icons.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderBatchSale(s,{slot,qualities=[],quote=null,error='',page=0}={}){
 const entries=(quote?.entries||[]).map(e=>{try{return {...e,item:JSON.parse(e.fingerprint)};}catch{return null;}}).filter(Boolean),pages=Math.max(1,Math.ceil(entries.length/12)),current=Math.max(0,Math.min(pages-1,Number.isInteger(page)?page:0)),shown=entries.slice(current*12,current*12+12),count=quote?.count??entries.length,gold=quote?.total??0;
 return `<section class="batchSalePanel"><div class="batchSaleHeading">${icon(slot||'bag')}<div><span class="eyebrow">SELL EQUIPMENT</span><h2>${SLOTNAME[slot]||'装备'}背包 · 批量出售</h2></div></div><div class="batchQualityChoices" aria-label="选择出售品质">${[...RARITY.slice(0,4),'传说'].map((name,q)=>`<button class="r${q}text" ${q===4?'style="color:#e7bc58"':''} data-batch-quality="${q}" aria-pressed="${qualities.includes(q)}">${qualities.includes(q)?'◆':'◇'} ${name}</button>`).join('')}</div><div class="batchSaleTotals"><span>本次预览 <b>${count}</b> 件</span><strong>${icon('gold')} ${gold} ◈</strong></div>${entries.length?`<div class="batchSaleItems">${shown.map(({item:it,id,value})=>`<div class="batchSaleItem r${equipmentDisplayQuality(it)} ${it.set?'setFrame':''}" title="${esc(it.name)} · ${value}金币">${equipmentIcon(it,{size:32})}<small>${value} ◈</small></div>`).join('')}</div>${pages>1?`<nav class="batchSalePages"><button data-batch-page="${current-1}" ${current===0?'disabled':''}>←</button><span>${current+1} / ${pages}</span><button data-batch-page="${current+1}" ${current===pages-1?'disabled':''}>→</button></nav>`:''}`:'<div class="batchSaleEmpty">'+(qualities.length?'当前选择没有可出售装备':'请先选择品质；默认不选中任何装备')+'</div>'}${error?`<p class="batchSaleError" role="alert">${esc(error)}</p>`:''}<p class="batchSaleRules">已穿戴、锁定、方案引用及待改造装备不会出售。<br>仅出售本次预览；期间新获得装备不加入。</p><div class="batchSaleActions">${!quote?'<button data-batch-refresh="1">重新预览</button>':''}<button data-batch-cancel="1">取消</button><button class="danger" data-batch-confirm="1" ${!quote||!count?'disabled':''}>确认出售 ${count} 件 · ${gold}◈</button></div></section>`;
}
